# from velocity_communicator.rest.query import RestQueryException
from copy import deepcopy
import os
import json
import time


class TemplatesPrivate(object):
    """
        Class with definicion of private methods related to
        CMaintenance module.
    """

    def _is_user_administrator(self):
        current_user = self.get_current_user()
        if current_user["role"] != "ADMIN":
            print(f'Current user role: {current_user["role"]}')
            raise Exception("User doesn't have ADMIN rights to perform operation!")

    def _get_template_id_by_name(self, template_name):
        templates = self.get_templates(filter=f'name::{template_name}')
        if templates["templates"] != []:
            for template in templates["templates"]:
                if template["name"] == template_name:
                    return template["id"]
        raise Exception(f"Template {template_name} not found")

    def _get_dropdown_available_values(self, template_info, property_name):
        for property_group in template_info["propertyGroups"]:
            for property in property_group["properties"]:
                if property["name"] == property_name:
                    return property["availableValues"]
        raise Exception(f'Property {property_name} not found in template' +
                        f'{template_info["name"]}')

    def _get_template_data(self, template_name):
        templates = self.get_templates(filter=f'name::{template_name}')
        if templates["templates"] == [] or \
            len(templates["templates"]) > 1:
            raise Exception(f"Template {template_name} not found or there is multible!")
        return self.get_template(templates["templates"][0]["id"])
    
    def _load_properties_json(self, file_name):
        config_path = os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
            'private',
            # 'support_services\\private',
        )
        # mypath = os.path.join(config_path, 'translation.json')
        mypath = os.path.join(config_path, file_name)
        with open(mypath) as json_file:
            data = json.load(json_file)
        return data

    def _template_resources_self_to_file(self, template, property_name):
        property_dict = {}
        devices = self._get_device_list(template["id"])
        property_dict["devices"] = len(devices)
        if len(devices) == 0:
            print(f'No devices under {template["name"]}')
            return property_dict
        for device in devices:
            for property in device["properties"]:
                if property["name"].lower() == property_name.lower():
                    property_dict[device["name"]] = property["value"]
        if property_dict != {}:
            return property_dict
        else:
            print(f'{template["name"]} resourses do not have ' +
                  f'{property_name} property')
            return 0

    def _get_device_list(self, parent_template_id):
        limit = 200
        devices = []
        resources = self.get_devices(limit=200,
                                     filter=f'templateId::{parent_template_id}',
                                     includeProperties=True)
        devices.extend(resources["devices"])
        total_all = resources["total"]
        offset = limit
        if total_all > limit:
            while offset < total_all:
                resources = self.get_devices(limit=200,
                                             filter=f'templateId::{parent_template_id}',
                                             includeProperties=True, offset=offset)
                devices.extend(resources["devices"])
                offset += limit
        return devices

    def _change_template(self, new_template_id, device_id):
        t_body = {
            "templateId": new_template_id
        }
        change_result = self.update_device(
                device_id=device_id,
                body=t_body)

        started_waiting = time.time()
        while change_result["templateId"] != new_template_id:
            if time.time() < started_waiting + 200:
                raise Exception("Template change failed!")
            print(f"Template not changed yet. Trying again in 2 seconds.")
            time.sleep(2)
            change_result = self.get_device(device_id)
        print(f"Template changed!")
